package com.bank.seating.service;

import com.bank.seating.model.Employee;
import java.util.List;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class SeatingPlanService {
    private static final Logger log = Logger.getLogger(SeatingPlanService.class.getName());

    public List<String> labels(List<Employee> employees) {
        log.info(() -> "Building seating labels for " + employees.size() + " employees");
        return employees.stream()
                .map(Employee::toLabel)   // clean method reference to the label
                .collect(Collectors.toList());
    }
}
