package com.bank.seating;

import com.bank.seating.model.Employee;
import com.bank.seating.service.SeatingPlanService;
import java.util.Arrays;
import java.util.List;
import java.util.logging.Logger;

public class Main {
    private static final Logger log = Logger.getLogger(Main.class.getName());

    public static void main(String[] args) {
        List<Employee> staff = Arrays.asList(
            new Employee("Rajesh", "IT"),
            new Employee("Priya",  "Sales"),
            new Employee("Amit",   null)   // missing dept → "Unknown"
        );

        List<String> labels = new SeatingPlanService().labels(staff);
        labels.forEach(l -> log.info(() -> "Seating entry: " + l));
    }
}
